input.command:
cd /workspace; H=pr/head/.claude/scripts/adversarial-review.sh; echo "=== argjson uses in process_findings loop region"; awk 'NR>=1255 && NR<=1330 && /argjson|validate_finding|_validate_finding_reason/ {print NR": "$0}' $H | cut -c1-160; echo "=== validate_finding / _validate_finding_reason defs"; grep -nE '^(validate_finding|_validate_finding_reason)\(\)' $H; L=$(grep -nE '^_validate_finding_reason\(\)' $H | cut -d: -f1); sed -n "${L},$((L+12))p" $H | cut -c1-160
P=$(ls -d "$HOME"/audit-tmp/proj.* | head -1); cd "$P"
echo "=== production-shape repro: main() with a voice returning a string element"
cp tests/unit/adversarial-review-companion.bats tests/unit/audit-repro-main.bats
cat >> tests/unit/audit-repro-main.bats <<'EOF'
@test "MAIN-X primary returns a findings array with a string element" {
    invoke_dissenter() { echo "$3" >> "$CALLS"; [[ -n "$5" ]] && _vq "$3" ok > "$5"; jq -nc '{content: "{\"findings\":[\"just a string\",{\"id\":\"DISS-002\",\"severity\":\"HIGH\",\"category\":\"config\",\"description\":\"ok.\",\"failure_mode\":\"fm\"}]}", tokens_input:1, tokens_output:1, cost_usd:0, latency_ms:1, schema_enforced:false}'; }
    rc=0; result=$(_run_main review) || rc=$?
    echo "main_rc=$rc result_len=${#result} envelope_exists=$([ -f "$OUT_DIR/adversarial-review.json" ] && echo yes || echo no)" >&3
    tail -3 "$T/stderr.log" | cut -c1-200 >&3
}
EOF
bats -f 'MAIN-X' tests/unit/audit-repro-main.bats 2>&1 | tail -8
